\title{Lossless Rectified Perception in Eleven Dimensions:\\
Exact Width, Sharp Frame Bounds, and Rigidity at the Optimum}
\author{Aristotle}
\date{17 August 2026}

\begin{document}
\maketitle

\begin{abstract}
We determine exactly how wide a single rectified-linear layer must be in order to process an
$n$-dimensional percept without information loss, and we analyse the geometry of the resulting
optimum. Writing a layer as $\Phi_{W,b}(x)_i = \relu(\langle w_i,x\rangle + b_i)$ for
$x \in \R^n$ and $i$ in a finite index set, we prove that $\Phi_{W,b}$ is injective only if the
layer has at least $2n$ units, and that $2n$ units suffice, realised by the positive/negative
split layer $x \mapsto (x^+,x^-)$, which even admits a \emph{linear} left inverse. In dimension
$n = 11$ the least lossless width is therefore exactly $22$. We upgrade injectivity to a metric
statement: the split layer is a frame with bounds $1/2$ and $1$, both attained, so the decoding
condition number is exactly $\sqrt{2}$ with antipodal percepts the unique worst case. We then
show that architectures at the width optimum are rigid: a lossless layer on $\R^n$ with exactly
$2n$ units admits two percepts whose active-unit sets partition the units into two blocks of
size exactly $n$, whence every unit has a nonzero weight row --- no dead units, no constant
detectors, no prunable redundancy. We prove that depth cannot repair a narrow sensory interface:
any network whose first hidden layer has fewer than $2n$ rectified units identifies two distinct
percepts, whatever the later layers compute; conversely towers of optimal split layers remain
lossless at every depth. For order-$k$ tensor percepts in $(\R^{11})^{\otimes k}$ the exact width
law is $2 \cdot 11^k$, i.e.\ $22$, $242$, $2662$ for $k=1,2,3$. Finally, permutation equivariance
reduces a linear perception layer to the two-parameter form $x \mapsto a x + b (\sum_j
x_j)\mathbf{1}$ with unique parameters, and adding sign equivariance reduces it to a scalar
multiple of the identity, destroying all cross-channel computation; while oddness of $11$
guarantees that every linear layer on $\R^{11}$ has an invariant percept direction, a guarantee
that fails in even dimension.
\end{abstract}

\noindent\textbf{Keywords:} rectified linear units, injective neural layers, frame bounds, width
lower bounds, equivariance, Deep Sets, hyperoctahedral group, tensor percepts.

\section{Introduction}

\subsection{The design question}
Consider a sensing system whose instantaneous state is an $11$-dimensional real vector: a
\emph{percept} $x \in \R^{11}$ whose coordinates are independent sensory channels. The canonical
first stage of a neural architecture applied to such a signal is a rectified-linear layer: a
finite family of units, each computing a rectified affine functional of the percept. Such a layer
is lossy by default, since $\relu(t) = \max(t,0)$ collapses the half-line $t \le 0$ to a point.
Whether the layer as a whole preserves the percept depends on how the units' half-spaces are
arranged. We answer exactly:
\begin{quote}
What is the minimal number of rectified units in an injective layer on $\R^n$, and what does an
architecture at that minimum look like?
\end{quote}
The answer is $2n$, hence $22$ for $n=11$, and the geometry at the optimum is fully determined.

\subsection{Why the naive answers fail}
\emph{``$n$ units suffice.''} This ignores rectification: the layer $x \mapsto (\relu(x_1),\dots,
\relu(x_n))$ sends every vector with all coordinates negative to the origin. \emph{``Enough random
units will do.''} True but uninformative: the threshold is exactly the point below which no
amount of downstream depth or capacity can help (Theorem~\ref{thm:depth}).

\subsection{Results}
Let $\iota$ be a finite index set of units, $W$ the weight matrix with rows $w_i \in \R^n$, and
$b : \iota \to \R$ the biases.
\begin{enumerate}
\item \textbf{Exact width law} (Theorems~\ref{thm:lower11}, \ref{thm:suff}, \ref{thm:least11}):
injectivity forces $|\iota| \ge 2n$, and $2n$ is attained; for $n = 11$ the least width is $22$.
\item \textbf{Sharp frame bounds} (Theorems~\ref{thm:upper}, \ref{thm:lower}, \ref{thm:sharp}).
\item \textbf{Rigidity at the optimum} (Theorems~\ref{thm:balanced}, \ref{thm:essential}).
\item \textbf{Depth is no substitute for interface width} (Theorem~\ref{thm:depth},
Proposition~\ref{prop:deep}).
\item \textbf{Tensor percepts} (Theorem~\ref{thm:tensor}).
\item \textbf{Equivariance costs} (Theorems~\ref{thm:deepsets}, \ref{thm:hyper},
\ref{thm:noswap}).
\item \textbf{The parity dividend} (Theorem~\ref{thm:parity}, Proposition~\ref{prop:rot}).
\end{enumerate}

\section{Definitions}

\begin{definition}[Rectifier]
$\relu : \R \to \R$, $\relu(t) = \max(t,0)$.
\end{definition}

We use constantly that $\relu(t) = 0$ for $t \le 0$, $\relu(t)=t$ for $t \ge 0$, and the
\emph{split identity}
\begin{equation}\label{eq:split}
\relu(t) - \relu(-t) = t \qquad (t \in \R).
\end{equation}

\begin{definition}[Pre-activation and layer]
Given a finite index set $\iota$, weights $W : \iota \to \R^n$ with rows $w_i$ and entries
$W_{ij}$, and biases $b : \iota \to \R$, the \emph{pre-activation} of unit $i$ at $x \in \R^n$ is
$p_i(x) = \sum_{j=1}^n W_{ij}x_j + b_i$, and the \emph{rectified layer} is
$\Phi_{W,b} : \R^n \to \R^\iota$, $\Phi_{W,b}(x)_i = \relu(p_i(x))$.
\end{definition}

\begin{definition}[Losslessness]
The layer is \emph{lossless} if $\Phi_{W,b}$ is injective.
\end{definition}

\begin{definition}[Active rows]\label{def:active}
$A(x) = \{\, i \in \iota : p_i(x) > 0 \text{ and } w_i \ne 0 \,\}$. The condition $w_i \ne 0$
excludes units constant in the input: such a unit may be ``on'' yet transmits nothing.
\end{definition}

\begin{definition}[Split layer]\label{def:split}
The \emph{positive/negative split layer} has index set $\{1,\dots,n\}\sqcup\{1,\dots,n\}$, zero
biases, and rows $w_{(+,i)} = e_i$, $w_{(-,i)} = -e_i$; explicitly
$\Phisplit(x) = (x^+, x^-)$ where $x^+_j = \relu(x_j)$, $x^-_j = \relu(-x_j)$.
\end{definition}

For finitely indexed vectors we write $d^2(x,y) = \sum_i (x_i-y_i)^2$.

\begin{lemma}[Small perturbation preserves inactivity]\label{lem:scale}
Let $S$ be finite and $p,c : S \to \R$ with $p_i < 0$ for all $i \in S$. Then there is $t>0$ with
$p_i + t c_i \le 0$ for all $i \in S$.
\end{lemma}
\begin{proof}
Take $t = \min_{i \in S} (-p_i)/(1+|c_i|) > 0$ (and $t=1$ if $S = \emptyset$). Then
$t(1+|c_i|) \le -p_i$ and $c_i \le |c_i|$, so $t c_i \le -p_i - t < -p_i$.
\end{proof}

\begin{lemma}[Far field dominates the biases]\label{lem:far}
Let $d,b : \iota \to \R$ with $\iota$ finite. There is $s>0$ with $|b_i| < s|d_i|$ for every $i$
with $d_i \ne 0$.
\end{lemma}
\begin{proof}
Take $s = 1 + \max\{|b_i|/|d_i| : d_i \ne 0\}$, or $s=1$ if no such $i$ exists.
\end{proof}

\section{The lower bound}

\begin{lemma}[Generic direction]\label{lem:generic}
For any finite family of rows $w_i \in \R^n$ there is $u \in \R^n$ with $\langle w_i,u\rangle \ne
0$ for every $i$ with $w_i \ne 0$.
\end{lemma}
\begin{proof}
Associate to each nonzero row the polynomial $P_i(X) = \sum_{j=1}^n W_{ij}X^{j-1}$, which is
nonzero since some $W_{ik} \ne 0$. The product $P = \prod_i P_i$ over nonzero rows is a nonzero
real polynomial, hence has a non-root $t \in \R$. With $u = (1,t,\dots,t^{n-1})$ we get
$\langle w_i, u \rangle = P_i(t) \ne 0$ for every nonzero row, since a nonzero product has all
factors nonzero.
\end{proof}

\begin{theorem}[Active rows span]\label{thm:rank}
Let $\Phi_{W,b}$ be injective and let $x$ be a percept at which no input-dependent unit sits on
its kink: for each $i$, either $w_i = 0$ or $p_i(x) \ne 0$. Then $\{w_i : i \in A(x)\}$ spans
$\R^n$; in particular $|A(x)| \ge n$.
\end{theorem}
\begin{proof}
Let $L : \R^n \to \R^{A(x)}$, $L(v)_i = \langle w_i, v\rangle$. We show $L$ is injective, whence
$n \le |A(x)|$ and the active rows span. Suppose $L(v)=0$, and set $c_i = \langle w_i, v\rangle$,
$S = \{i : c_i \ne 0\}$. For $i \in S$ we have $w_i \ne 0$, hence $p_i(x) \ne 0$; and $p_i(x)>0$
would put $i$ in $A(x)$, forcing $c_i = 0$. So $p_i(x) < 0$ on $S$. By Lemma~\ref{lem:scale}
choose $t>0$ with $p_i(x) + t c_i \le 0$ on $S$. Since $p_i(x+tv) = p_i(x) + t c_i$: units with
$c_i = 0$ are unchanged, and units with $c_i \ne 0$ output $0$ at both $x$ and $x+tv$. Hence
$\Phi_{W,b}(x+tv) = \Phi_{W,b}(x)$, so $x+tv=x$ by injectivity, so $v = 0$.
\end{proof}

\begin{theorem}[Antipodal probes]\label{thm:antipodal}
If $\Phi_{W,b}$ is injective then there are percepts $x,y$ with $|A(x)| \ge n$, $|A(y)| \ge n$
and $A(x) \cap A(y) = \emptyset$.
\end{theorem}
\begin{proof}
Choose $u$ by Lemma~\ref{lem:generic}, set $d_i = \langle w_i, u\rangle$, and choose $s>0$ by
Lemma~\ref{lem:far}. Along $\sigma \mapsto \sigma u$ we have $p_i(\sigma u) = \sigma d_i + b_i$.
If $|\sigma| = s$ and $w_i \ne 0$ then $\sigma d_i + b_i = 0$ would give $|b_i| = s|d_i|$,
contradicting $|b_i| < s|d_i|$; so $x = su$ and $y = -su$ satisfy the hypothesis of
Theorem~\ref{thm:rank}, giving both cardinality bounds. For disjointness, suppose $i \in A(x)
\cap A(y)$. Then $w_i \ne 0$ and $d_i \ne 0$, and $sd_i + b_i > 0$, $-sd_i + b_i > 0$. If
$sd_i>0$ the second gives $b_i > |sd_i|$; if $sd_i<0$ the first gives $b_i > |sd_i|$. Either way
$|b_i| > s|d_i|$, contradicting the choice of $s$.
\end{proof}

\begin{theorem}[Width lower bound]\label{thm:lower2n}
If $\Phi_{W,b} : \R^n \to \R^\iota$ is injective then $|\iota| \ge 2n$.
\end{theorem}
\begin{proof}
With $x,y$ as above, $2n \le |A(x)| + |A(y)| = |A(x) \cup A(y)| \le |\iota|$.
\end{proof}

\begin{theorem}[Eleven dimensions]\label{thm:lower11}
A lossless rectified perception layer on $\R^{11}$ has at least $22$ units; equivalently, no
layer on $\R^{11}$ with fewer than $22$ units is injective. \qed
\end{theorem}

\begin{remark}
A rectified unit is a half-space detector. Injectivity requires a full-rank measurement on both
far sides of a generic line, and no unit can serve both sides. The factor $2$ is exactly the cost
of one-sidedness.
\end{remark}

\section{The matching construction}

\begin{theorem}[Exact linear reconstruction]\label{thm:recon}
For all $x \in \R^n$ and all $j$, $\Phisplit(x)_{(+,j)} - \Phisplit(x)_{(-,j)} = x_j$.
\end{theorem}
\begin{proof}
The split identity \eqref{eq:split} with $t = x_j$.
\end{proof}

\begin{theorem}[Sufficiency]\label{thm:suff}
$\Phisplit$ is injective; indeed it has the linear left inverse $(u,v) \mapsto u - v$. \qed
\end{theorem}

\begin{theorem}[Exact width law in dimension 11]\label{thm:least11}
$22$ is the least element of $\{ m : \exists\, W \in \R^{m\times 11},\, b \in \R^m,\,
\Phi_{W,b} \text{ injective}\}$.
\end{theorem}
\begin{proof}
Membership: the split layer at $m=22$ (Theorem~\ref{thm:suff}), re-indexed by any bijection of
unit labels, which clearly preserves injectivity. Minimality: Theorem~\ref{thm:lower11}.
\end{proof}

\section{Sharp frame bounds}

\begin{lemma}[Coordinatewise sandwich]\label{lem:sandwich}
For all $a,b \in \R$,
\[
\frac{(a-b)^2}{2} \;\le\; \big(\relu(a)-\relu(b)\big)^2 + \big(\relu(-a)-\relu(-b)\big)^2
\;\le\; (a-b)^2 .
\]
\end{lemma}
\begin{proof}
Put $u = \relu(a)-\relu(b)$, $v = \relu(-a)-\relu(-b)$; by \eqref{eq:split}, $u - v = a-b$, and
$(u-v)^2 \le 2(u^2+v^2)$ gives the lower bound. For the upper bound, check four sign cases: if
$a,b$ have the same sign, one of $u,v$ vanishes and the other is $\pm(a-b)$, giving equality; if
they straddle zero, say $a \le 0 \le b$, then $u^2+v^2 = a^2+b^2 \le a^2 - 2ab + b^2 = (a-b)^2$
since $-2ab \ge 0$.
\end{proof}

\begin{theorem}[Upper frame bound]\label{thm:upper}
$d^2(\Phisplit(x),\Phisplit(y)) \le d^2(x,y)$ for all $x,y \in \R^n$. \qed
\end{theorem}

\begin{theorem}[Lower frame bound]\label{thm:lower}
$\tfrac12 d^2(x,y) \le d^2(\Phisplit(x),\Phisplit(y))$ for all $x,y \in \R^n$. \qed
\end{theorem}

Both follow by summing Lemma~\ref{lem:sandwich} over coordinates, using
$d^2(\Phisplit(x),\Phisplit(y)) = \sum_j\big[(\relu(x_j)-\relu(y_j))^2 +
(\relu(-x_j)-\relu(-y_j))^2\big]$.

\begin{corollary}
$\Phisplit$ is a frame with bounds $1/2$ and $1$; the worst-case decoding amplification is
$\sqrt2$. The lower bound re-proves injectivity: equal outputs force $d^2(x,y) \le 0$. \qed
\end{corollary}

\begin{theorem}[Both constants attained, $n=11$]\label{thm:sharp}
With $e_0$ the first standard basis vector,
\[
d^2(\Phisplit(e_0),\Phisplit(0)) = 1 = d^2(e_0,0), \qquad
d^2(\Phisplit(e_0),\Phisplit(-e_0)) = 2 = \tfrac12 d^2(e_0,-e_0).
\]
\end{theorem}
\begin{proof}
Direct computation: in the first case only the unit $(+,0)$ changes; in the second, the outputs
are $e_{(+,0)}$ and $e_{(-,0)}$, at squared distance $2$, while $\|2e_0\|^2 = 4$.
\end{proof}

Thus the unique worst case is an antipodal pair: rectification loses exactly a factor two of
energy across a sign flip, and nothing worse can occur.

\begin{proposition}[General contraction]
For any rectified layer, $d^2(\Phi_{W,b}(x),\Phi_{W,b}(y)) \le \sum_i (p_i(x)-p_i(y))^2$.
\end{proposition}
\begin{proof}
$\relu$ is $1$-Lipschitz, since $|\max(s,0)-\max(t,0)| \le |s-t|$; square and sum.
\end{proof}

\section{Depth cannot repair a narrow interface}

\begin{theorem}[Narrow first layer is fatal at any depth]\label{thm:depth}
Let $\Phi_{W,b} : \R^{11} \to \R^\iota$ with $|\iota| < 22$, and let $g : \R^\iota \to
\mathcal{A}$ be an arbitrary map into an arbitrary set --- any composition of further layers,
nonlinearities, normalisations or attention blocks. Then $g \circ \Phi_{W,b}$ is not injective.
\end{theorem}
\begin{proof}
If $g \circ \Phi_{W,b}$ is injective then so is $\Phi_{W,b}$, since $\Phi_{W,b}(x) =
\Phi_{W,b}(y)$ implies $g(\Phi_{W,b}(x)) = g(\Phi_{W,b}(y))$ and hence $x = y$. This contradicts
Theorem~\ref{thm:lower11}.
\end{proof}

\begin{proposition}[Depth is otherwise free]\label{prop:deep}
The composition of the split layer $\R^n \to \R^{2n}$ with the split layer $\R^{2n} \to \R^{4n}$
is injective, and inductively towers of split layers are injective at every depth. \qed
\end{proposition}

\section{Rigidity at the optimum}

\begin{theorem}[Balanced activation]\label{thm:balanced}
Let $\Phi_{W,b} : \R^n \to \R^\iota$ be injective with $|\iota| = 2n$ exactly. Then there are
percepts $x,y$ with
\[
|A(x)| = n, \quad |A(y)| = n, \quad A(x) \cap A(y) = \emptyset, \quad A(x) \cup A(y) = \iota .
\]
\end{theorem}
\begin{proof}
Take $x,y$ from Theorem~\ref{thm:antipodal}. Disjointness gives $|A(x)|+|A(y)| = |A(x)\cup A(y)|
\le 2n$, while each term is $\ge n$; hence both equal $n$ and the union, having $2n$ elements
inside a $2n$-element set, is all of $\iota$.
\end{proof}

\begin{theorem}[Every unit is essential]\label{thm:essential}
Under the hypotheses of Theorem~\ref{thm:balanced}, every unit $i$ has $w_i \ne 0$.
\end{theorem}
\begin{proof}
Each $i$ lies in $A(x)$ or $A(y)$, and membership requires $w_i \ne 0$ by
Definition~\ref{def:active}.
\end{proof}

\begin{corollary}
A lossless $22$-unit layer on $\R^{11}$ has no constant detector and no removable unit: deleting
a unit leaves $21 < 22$, which cannot be lossless. \qed
\end{corollary}

\begin{proposition}
For the split layer and any percept $x$ with all coordinates strictly positive, the active units
are exactly the $n$ units of the positive block; reversing the percept exchanges the blocks.
\end{proposition}
\begin{proof}
Unit $(+,j)$ has pre-activation $x_j > 0$ with nonzero row; unit $(-,j)$ has $-x_j < 0$.
\end{proof}

No assumption on the weights is made in Theorem~\ref{thm:balanced}, yet the layer is forced to
exhibit the signature of the canonical positive/negative split: two disjoint, exactly balanced
blocks of $n$ units activated by an antipodal pair of probes.

\section{Order-$k$ tensor percepts}

An order-$k$ eleven-dimensional percept is an element of $(\R^{11})^{\otimes k}$, i.e.\ a
function $\{1,\dots,11\}^k \to \R$, a space of dimension $11^k$.

\begin{theorem}[Exact tensor width law]\label{thm:tensor}
A lossless rectified layer on order-$k$ eleven-dimensional tensor percepts needs at least
$2\cdot 11^k$ units, and $2\cdot 11^k$ units suffice.
\end{theorem}
\begin{proof}
Lower bound: Theorem~\ref{thm:lower2n} with $n = 11^k$. Upper bound: the coordinatewise split
layer on $\R^{11^k}$ (Theorem~\ref{thm:suff}), of width $2 \cdot 11^k$.
\end{proof}

\begin{corollary}
The lossless widths are $22$, $242$, $2662$ for $k = 1,2,3$. \qed
\end{corollary}

The overhead of losslessness is a constant factor $2$ at every order; the base cost, however,
grows as $11^k$, so lossless order-$3$ processing already requires thousands of interface units.

\section{The cost of symmetry}

Throughout, $M \in \R^{n\times n}$ acts by $L_M(x)_i = \sum_j M_{ij}x_j$ and $n \ge 2$.

\begin{definition}
$M$ is \emph{permutation equivariant} if $M_{\sigma(i)\sigma(j)} = M_{ij}$ for all $i,j$ and all
permutations $\sigma$ of the axes, equivalently if $L_M$ commutes with the permutation action on
coordinates. $M$ is \emph{sign equivariant} if $L_M(\varepsilon \odot x) = \varepsilon \odot
L_M(x)$ for every $\varepsilon \in \{\pm1\}^n$, with $\odot$ the coordinatewise product.
\end{definition}

\begin{theorem}[Deep Sets form]\label{thm:deepsets}
$M$ is permutation equivariant if and only if there are $a,b \in \R$ with $M_{ij} = a$ for $i=j$
and $M_{ij} = b$ for $i \ne j$; equivalently
\[
L_M(x)_i = (a-b)\,x_i + b\sum_{j=1}^n x_j \qquad \text{for all } x,i,
\]
and the pair $(a,b)$ is uniquely determined by $M$.
\end{theorem}
\begin{proof}
Permutation equivariance is invariance of the entries under $M_{ij} \mapsto
M_{\sigma(i)\sigma(j)}$. The symmetric group acts transitively on diagonal positions and, being
$2$-transitive, transitively on ordered pairs of distinct positions; hence a common diagonal
value $a$ and a common off-diagonal value $b$. Writing $M_{ij} = b + (a-b)\delta_{ij}$ and
summing gives the displayed form. Uniqueness: $a = M_{11}$, $b = M_{12}$, using $n \ge 2$.
\end{proof}

\begin{theorem}[Sign equivariance kills off-diagonal weights]\label{thm:sign}
If $M$ is sign equivariant then $M_{ij} = 0$ for all $i \ne j$.
\end{theorem}
\begin{proof}
Fix $i \ne j$; take $\varepsilon_j = -1$ and $\varepsilon_k = 1$ otherwise, and $x = e_j$. The
$i$-th coordinate of $L_M(\varepsilon \odot x)$ is $-M_{ij}$, while that of $\varepsilon \odot
L_M(x)$ is $\varepsilon_i M_{ij} = M_{ij}$. Hence $M_{ij} = 0$.
\end{proof}

\begin{theorem}[Hyperoctahedral rigidity]\label{thm:hyper}
For $n \ge 2$, a linear layer is equivariant for the full hyperoctahedral group
$B_n = \{\pm1\}^n \rtimes S_n$ if and only if $M = aI$ for some $a \in \R$. In particular a
$B_{11}$-equivariant perception layer on $\R^{11}$ is a global gain control $x \mapsto a x$ with a
single learnable parameter.
\end{theorem}
\begin{proof}
Necessity: Theorem~\ref{thm:deepsets} gives the two-parameter form and Theorem~\ref{thm:sign}
forces $b = 0$. Sufficiency: scalars commute with permutation matrices and diagonal sign
matrices.
\end{proof}

\begin{theorem}[No symmetric channel mixing]\label{thm:noswap}
No $B_{11}$-equivariant linear layer on $\R^{11}$ realises the exchange of two perception
channels, i.e.\ there is no such $M$ with $L_M(x) = x \circ (0\;1)$ for all $x$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:hyper}, $L_M(x) = ax$. At $x = e_1$ the zeroth coordinate of $ax$ is $0$,
while the swap requires $x_1 = 1$.
\end{proof}

The symmetry hierarchy for $n = 11$ is thus $121 \to 2 \to 1$ parameters, and the last step
annihilates all cross-channel computation: if the channels are genuinely interchangeable and
sign-symmetric, all expressivity must come from the nonlinearity or from deliberately broken
symmetry.

\section{The parity dividend}

\begin{theorem}[Invariant percept direction]\label{thm:parity}
Every linear perception layer on $\R^{11}$, with no hypothesis on the weights, has an invariant
percept direction: there are $a \in \R$ and $v \ne 0$ with $Mv = av$. If the layer is injective
then $a \ne 0$.
\end{theorem}
\begin{proof}
The characteristic polynomial is monic of odd degree $11$, hence tends to $\pm\infty$ at
$\pm\infty$ and has a real root $a$ by the intermediate value theorem; any nonzero kernel vector
of $aI - M$ is the required $v$. If $L_M$ is injective and $a = 0$ then $L_M(v) = 0 = L_M(0)$
gives $v = 0$, a contradiction.
\end{proof}

\begin{proposition}[Parity is essential]\label{prop:rot}
In dimension $2$ the quarter-turn layer $M = \left(\begin{smallmatrix} 0 & -1 \\ 1 & 0
\end{smallmatrix}\right)$ has no invariant percept direction.
\end{proposition}
\begin{proof}
$Mv = av$ reads $-v_2 = a v_1$, $v_1 = a v_2$; substituting, $(1+a^2)v_2 = 0$, so $v_2 = 0$, and
symmetrically $v_1 = 0$.
\end{proof}

\section{Exact numerical experiments}

All computations below are exact in rational arithmetic.

\paragraph{Collision one unit below the optimum.}
Take the $21$-unit layer with all $11$ positive detectors but only $10$ negative detectors (the
negative detector of channel $11$ is missing), and the percepts $x_A = (0,\dots,0,-1)$,
$x_B = (0,\dots,0,-2)$. Every unit outputs $0$ at both percepts, so the layer identifies
$x_A \ne x_B$: an explicit certificate that $21$ units do not suffice.

\paragraph{Frame ratios.}
For the optimal split layer, let $\rho(x,y) = d^2(\Phisplit(x),\Phisplit(y))/d^2(x,y)$, and put
$v_1 = (j-5)_{j=0}^{10}$, $v_2 = ((j-3)(-1)^j)_{j=0}^{10}$.

